 a=ic[np.array(by)>=cut];print(name,'n',len(a),'IC',a.mean(),'ICIR',a.mean()/a.std(ddof=1),'hit',np.mean(a>0))
for h in [1,5,10,20]:
 yy=px.shift(-h)/px-1;aa=[]
 for d in sig.index:
  q=pd.concat([sig.loc[d],yy.loc[d]],axis=1).dropna()
  if len(q)>=8:
   v=q.iloc[:,0].rank().corr(q.iloc[:,1].rank())
