D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').close for s in U}
p=pd.concat(D,axis=1).sort_index().loc[:end]
r=p.pct_change(); r20=p.pct_change(20); vol=r.rolling(20,min_periods=15).std()*np.sqrt(20)
# Relative return divided by own trailing risk; higher signal means relatively weak and/or risky.
f=(-(r20.sub(r20.median(axis=1),axis=0))/vol).rolling(5,min_periods=3).mean().shift(1)
rows=[]
for h in [10,20,40,60]:
