import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
series={}
for s in U:
 d=get_stock_daily_data(s,days=4200)
 if d is not None and len(d)>300:
  series[s]=d[['date','close']].dropna().drop_duplicates('date').set_index('date')['close'].astype(float)
p=pd.DataFrame(series).sort_index(); r=np.log(p).diff()
# Contrarian medium-term return scaled by downside semideviation; lag signal one day.
down=r.where(r<0).rolling(30,min_periods=12).std()*np.sqrt(252)
f=(-p.pct_change(60)/down).shift(1)
frs={h:p.shift(-h)/p-1 for h in [5,10,20,40,60]}
allq={}
for h,fr in frs.items():
 vals=[]; dates=[]; ns=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
   vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); dates.append(dt); ns.append(len(z))
 q=pd.Series(vals,index=pd.to_datetime(dates)).dropna(); allq[h]=q
 print('H',h,'valid_dates',len(q),'avgN %.2f'%np.mean(ns),'IC %.6f ICIR %.6f hit %.4f'%(q.mean(),q.mean()/q.std(),(q>0).mean()))
q=allq[20]; print('DETAIL coverage %.4f turnover %.6f'%(np.mean([len(pd.concat([f.loc[d],frs[20].loc[d]],axis=1).dropna()) for d in q.index])/len(U),f.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean()))
for a,b in [('2024-01-01','2026-12-31'),('2027-01-01','2029-12-31'),('2030-01-01','2030-12-31'),('2031-01-01','2031-11-26')]:
 z=q.loc[a:b]; print('REGIME',a[:4],len(z),'IC %.6f ICIR %.6f hit %.4f'%(z.mean(),z.mean()/z.std(),(z>0).mean()))
out=f.stack().rename('signal').reset_index(); out.columns=['date','symbol','signal']; out.to_csv('scripts/miner_3_20311127_downside_adjusted_reversal_signal.csv',index=False)

