U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
px={}
for s in U:
 d=get_stock_daily_data(s,days=4800)
 if d is not None and len(d)>120: px[s]=d[['date','close']].dropna().drop_duplicates('date').set_index('date').close.astype(float)
p=pd.DataFrame(px).sort_index(); r=p.pct_change()
d=get_index_daily_data('VIX',days=4800)
v=d[['date','close']].dropna().drop_duplicates('date').set_index('date').close.astype(float).reindex(p.index).ffill()
# Reversal after a short, volatility-normalized shock, amplified only when VIX has risen recently.
shock=-p.pct_change(10)/(r.rolling(20,min_periods=15).std()*np.sqrt(252)+0.05)
vshock=(v.pct_change(5)/(v.rolling(252,min_periods=100).std()+1e-8)).clip(-4,4)
f=shock.mul((1+0.35*np.tanh(vshock.shift(1).fillna(0))),axis=0).shift(1).replace([np.inf,-np.inf],np.nan)
print('DATA dates',len(p),'instruments',len(px),'range',p.index.min(),p.index.max())
for h in [10,20,40,60]:
 fr=p.shift(-h)/p-1; qs=[];ns=[];ds=[]
 for dt in f.index:
  z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
   qs.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'));ns.append(len(z));ds.append(dt)
 q=pd.Series(qs,index=pd.to_datetime(ds)).dropna()
 print('H %d dates %d avgN %.2f IC %.6f ICIR %.6f hit %.4f'%(h,len(q),np.mean(ns),q.mean(),q.mean()/q.std(),(q>0).mean()))
 if h==20:
  for a,b in [('2020-01-01','2023-12-31'),('2024-01-01','2026-12-31'),('2027-01-01','2029-12-31'),('2030-01-01','2030-12-31'),('2031-01-01','2032-12-31'),('2033-01-01','2033-03-02')]:
   z=q.loc[a:b]
   if len(z): print('REGIME',a[:4],len(z),'IC %.6f ICIR %.6f hit %.4f'%(z.mean(),z.mean()/z.std(),(z>0).mean()))
print('COVERAGE %.6f TURNOVER %.6f'%(f.notna().mean().mean(),f.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean()))
out=f.stack().rename('signal').reset_index();out.columns=['date','symbol','signal'];out.to_csv('scripts/miner_3_20330317_vix_shock_reversal_signal.csv',index=False)

