  cl[s]=d[['date','close']].dropna().drop_duplicates('date').set_index('date').close.astype(float)
p=pd.DataFrame(cl).sort_index(); r=p.pct_change(); peer=r.median(axis=1); resid=r.sub(peer,axis=0)
